/**
 * Tear down the copy-on-write state of a client, removing the diff
 * file if one was created. The master file is left untouched, so all
 * writes performed during the connection are discarded.
 *
 * @param client the client whose copy-on-write state we're cleaning up
 **/
static void cleanup_cow(CLIENT *client) {
	if(!client->difffilename)
		return;
	close(client->difffile);
	client->difffile = -1;
	if(unlink(client->difffilename) < 0) {
		msg(LOG_INFO, "Could not remove copy-on-write diff file %s: %s",
		    client->difffilename, strerror(errno));
	}
	g_free(client->difffilename);
	client->difffilename = NULL;
	g_clear_pointer(&client->difmap, g_free);
	g_clear_pointer(&client->diffpos, g_hash_table_unref);
	client->difffilelen = 0;
}

static inline void finalize_client(CLIENT* client) {
	g_thread_pool_free(tpool, FALSE, TRUE);
	do_run(client->server->postrun, client->exportname);
	if(client->transactionlogfd != -1)
		cleanup_transactionlog(client);
	cleanup_cow(client);
	pthread_mutex_destroy(&client->cowlock);

	serve_dec_ref(client->server);
}

static inline void socket_closed_transmission(CLIENT* client) {
	int saved_errno = errno;
	finalize_client(client);
	errno = saved_errno;
	err("Connection dropped: %m");
}

